    int tankSlot=Array.FindIndex(s.Defense,x=>x.Definition?.Kind is "ShieldBoost" or "ArmorRepair");s.Shield=s.MaxShield*.5f;s.Armor=s.MaxArmor*.5f;s.Cap=s.MaxCap;float hp=s.Shield+s.Armor;Check(w.ToggleDefense(tankSlot),"local repair activates "+h.Name);w.UpdateDefense(30);Check(s.Shield+s.Armor>hp,"live local repair "+h.Name);
    Check(w.ToggleSpecial(bi)&&s.Special[bi].Active&&s.Special[bi].StopRequested,"committed stop queue "+h.Name);w.Save();var saved=new DemoWorld();Check(saved.Load()&&saved.Player.HasSpecial("Bastion")&&saved.Player.Special[bi].StopRequested,"active siege save/load "+h.Name);w.UpdateSpecial(s.Special[bi].CycleLeft+.01f);Check(!s.HasSpecial("Bastion")&&!w.SpecialMicroBlocked&&s.Stat("remoteRepairImpedance")>0,"boundary release "+h.Name);
    int mj=Array.FindIndex(s.Mobility,x=>x.Definition?.Kind=="MJD");Check(mj>=0,"large MJD installed "+h.Name);s.Cap=s.MaxCap;s.Facing=Vector3.UnitZ;Vector3 origin=s.Position;Check(w.ToggleMobility(mj),"MJD spools after siege "+h.Name);w.UpdateMobility(s.Mobility[mj].CycleLeft+.01f);Check(Vector3.Distance(s.Position,origin)>90000&&s.Mobility[mj].Cooldown>0,"actual MJD displacement and cooldown "+h.Name);
   }else{
    Check(s.Special.Any(x=>x.Definition?.Kind=="CovertPortal")&&s.Special.Any(x=>x.Definition?.Kind=="CovertCyno"),"bridge and cyno installed "+h.Name);Check(w.SpecialFitError(SpecialCatalog.ById["sp_ghost"],7).Length>0,"reject covert cloak "+h.Name);
    int ci=Array.FindIndex(s.Special,x=>x.Definition?.Kind=="Cloak");double speed=s.Stat("maxVelocity");Check(w.ToggleSpecial(ci)&&w.Cloaked&&w.WarpBlocked("player"),"standard cloak active and warp blocked "+h.Name);double expected=p.Traits.Length==0?.12:.9;Check(Near(s.Stat("maxVelocity")/speed,expected),"source cloak speed "+h.Name);w.ToggleSpecial(ci);Check(Near(s.Special[ci].Cooldown,p.Traits.Length==0?31.2:5)&&Near(w.SpecialLockRecovery,p.Traits.Length==0?31.2:0),"source decloak timers "+h.Name);
    w.SystemId="rook";s.Cap=s.MaxCap;w.JumpDriveCooldown=0;var b=new JumpBeacon{System="umbra",Kind="CovertCyno",Left=600};w.JumpBeacons.Add(b);w.JumpBeaconSelection=b.Id;float fuel=w.ItemCount("jump_fuel",false);int need=w.JumpFuelRequired(b.System);double distance=DemoWorld.BeaconDistance(w.SystemId,b.System);Check(w.JumpToBeacon(b.System)&&w.SystemId==b.System&&Near(w.ItemCount("jump_fuel",false),fuel-need),"actual jump and exact fuel "+h.Name);Check(w.JumpFatigue>0&&w.JumpFatigue<=300*distance*s.Stat("jumpFatigueMultiplier")+.01,"source jump fatigue "+h.Name);
   }
   var copy=FittingSimulation.Copy(s);Check(Near(copy.TotalDps,s.TotalDps)&&copy.Special.Select(x=>x.ModuleId).SequenceEqual(s.Special.Select(x=>x.ModuleId)),"detached simulator preserves elite fit "+h.Name);w.Save();var l=new DemoWorld();Check(l.Load()&&l.Player.CombatHull==s.CombatHull&&l.Player.Special.Select(x=>x.ModuleId).SequenceEqual(s.Special.Select(x=>x.ModuleId)),"ship fitting saves "+h.Name);Console.WriteLine("BATCH29 PASS: "+h.Faction+" / "+h.Name+" / "+p.Role);
  }
  var hybrid=WeaponCatalog.All.First(x=>x.Size==3&&x.Family=="Railguns");var laser=WeaponCatalog.All.First(x=>x.Size==3&&x.Laser);var proj=WeaponCatalog.All.First(x=>x.Size==3&&x.Family=="Autocannons");var cruise=WeaponCatalog.All.First(x=>x.Family=="Missile Launcher Cruise");var rapid=WeaponCatalog.All.First(x=>x.Family=="Missile Launcher Rapid Heavy");var light=WeaponCatalog.All.First(x=>x.Family=="Missile Launcher Rapid Light");var entropic=WeaponCatalog.All.First(x=>x.Kind==WeaponKind.Entropic&&x.Size==3);
  Check(Near(Hull("Kronos").HullWeapon(hybrid,"damage"),2.5)&&Near(Hull("Sin").HullWeapon(hybrid,"damage"),2),"Kronos and Sin V large hybrid factors");Check(Near(Hull("Kronos").HullWeapon(WeaponCatalog.All.First(x=>x.Size==2&&x.Family=="Railguns"),"damage"),1),"large scope excludes medium weapons");
  Check(Near(Hull("Widow").HullWeapon(rapid,"cycle"),.5)&&Near(Hull("Widow").HullWeapon(light,"cycle"),1),"Widow V rapid heavy excludes rapid light");Check(Near(Hull("Golem").HullWeapon(rapid,"damage"),2)&&Near(Hull("Golem").HullWeapon(light,"damage"),1)&&Near(Hull("Golem").HullWeapon(cruise,"missileVelocity"),1.5),"Golem heavy missile damage and cruise velocity filters");
  Check(Near(Hull("Redeemer").HullWeapon(laser,"cap"),.5)&&Near(Hull("Redeemer").HullWeapon(laser,"cycle"),.5),"Redeemer V cost and cycle");Check(Near(Hull("Panther").HullWeapon(proj,"damage"),1.5)&&Near(Hull("Panther").HullWeapon(proj,"cycle"),.75),"Panther V damage and cycle");
  Check(Near(Hull("Paladin Tash-Murkon Edition").HullWeapon(laser,"optimal"),1.25*1.375)&&Near(Hull("Paladin Tash-Murkon Edition").HullWeapon(laser,"cap"),1),"legacy independent duplicated optimal traits preserved");Check(Near(Hull("Paladin Kador Edition").HullFactor("hull","capacitorCapacity"),1.25),"legacy Kador capacitor trait");
  Check(Near(Hull("Vargur").HullWeapon(proj,"damage"),2.75)&&Near(Hull("Vargur Justice Edition").HullWeapon(proj,"cycle"),.75),"modern vs legacy Vargur traits");
  foreach(string name in new[]{"Python","GFX Test Vargur 1/2","GFX Test Vargur 2/2"})Check(Hull(name).ActiveHullTraits.Length==0&&Near(Hull(name).HullWeapon(proj,"damage"),1),"no invented prototype traits "+name);
  Check(Near(Hull("Kronos").HullFactor("prop","reactivation","MJD"),1)&&Near(Hull("Kronos Police Edition").HullFactor("prop","reactivation","MJD"),.3),"MJD legacy only seventy percent reduction");
  var scram=EwarCatalog.All.First(x=>x.Kind==EwarKind.Scram);var point=EwarCatalog.All.First(x=>x.Kind==EwarKind.Point);Check(Near(Hull("Sin").HullEwar(scram)!.Strength,scram.Strength+5)&&Near(Hull("Sin").HullEwar(scram)!.Optimal/scram.Optimal,1.5)&&Near(Hull("Sin").HullEwar(point)!.Optimal/point.Optimal,1),"Sin additive scramble strength excludes disruptors");
  foreach(var e in EwarCatalog.All.Where(x=>x.Kind is EwarKind.ECM or EwarKind.BurstJam))Check(Near(Hull("Widow").HullEwar(e)!.Strength/e.Strength,3),"Widow V targeted and burst ECM");var grapple=EwarCatalog.All.First(x=>x.Kind==EwarKind.Grapple);Check(Near(Hull("Panther").HullEwar(grapple)!.Optimal/grapple.Optimal,2),"Panther V heavy grappler range");
  Check(Near(Hull("Babaroga").HullWeapon(entropic,"rampMax"),2)&&Near(Hull("Babaroga").HullWeapon(entropic,"damage"),1)&&Near(Hull("Babaroga").HullWeapon(entropic,"optimal"),1.375),"Babaroga max ramp distinct from flat damage");var remote=SupportCatalog.All.First(x=>x.Kind=="Armor");Check(Near(Hull("Babaroga").HullSupport(remote)!.Optimal/remote.Optimal,2)&&Near(Hull("Babaroga").HullSupport(remote)!.Capacitor/remote.Capacitor,.5),"Babaroga remote repair reach and cap");
  var marshal=Hull("Marshal");marshal.PilotSecurity=5;Check(Near(marshal.SecurityRepairFactor("ShieldBoost"),1.5)&&Near(marshal.SecurityGainFactor,1.1),"Marshal positive security repair and pirate gain");marshal.PilotSecurity=-5;Check(Near(marshal.SecurityRepairFactor("ArmorRepair"),1),"Marshal negative security floor");
