 static void BridgeChecks(Func<string,DemoWorld> owned,Action<bool,string> check,Func<double,double,bool> near)
 {
  DemoWorld Fixture(){var w=owned("Sin");w.HireWingmate("Escort");w.AssignFleetHull(w.Wingmates[0].Id,"covert");w.Undock();w.SystemId="rook";w.Wingmates[0].System="rook";w.Targets.Where(t=>t.Id!=w.Wingmates[0].Id).ToList().ForEach(t=>w.Targets.Remove(t));w.Targets.First().Position=w.Player.Position+new Vector3(3000,0,0);var b=new JumpBeacon{System="umbra",Kind="CovertCyno",Left=600};w.JumpBeacons.Add(b);w.JumpBeaconSelection=b.Id;w.Player.Cap=w.Player.MaxCap;check(w.ToggleSpecial(Array.FindIndex(w.Player.Special,x=>x.Definition?.Kind=="CovertPortal")),"real portal activation");return w;}
  var bridge=Fixture();string origin=bridge.SystemId;float fuel=bridge.ItemCount("jump_fuel",false);check(bridge.BridgeSpecial(false)&&bridge.SystemId==origin&&bridge.Wingmates[0].System=="umbra"&&bridge.ItemCount("jump_fuel",false)<fuel,"bridge sends ally and leaves anchor");
  var conduit=Fixture();float before=conduit.ItemCount("jump_fuel",false);double distance=DemoWorld.BeaconDistance(conduit.SystemId,"umbra");check(conduit.BridgeSpecial(true)&&conduit.SystemId=="umbra"&&conduit.Wingmates[0].System=="umbra"&&conduit.LastBridgePassengers==1,"conduit carries anchor and ally");check(near(conduit.ItemCount("jump_fuel",false),before-Math.Ceiling(1000*distance))&&near(conduit.JumpFatigue,300*distance*.25),"conduit exact fixed fuel and source fatigue");conduit.Save();var loaded=new DemoWorld();check(loaded.Load()&&loaded.SystemId==conduit.SystemId&&loaded.Wingmates[0].System==conduit.Wingmates[0].System&&near(loaded.JumpFatigue,conduit.JumpFatigue),"travel fleet positions and fatigue save/load");
  var capacity=Fixture();capacity.Wingmates.Clear();capacity.Targets.Clear();for(int i=0;i<32;i++){var profile=new Ship();profile.SetCombatHull("covert");var ally=new Wingmate{Id="passenger-"+i,HullId="covert",Shield=profile.MaxShield,Armor=profile.MaxArmor,Hull=profile.MaxHull,Cap=profile.MaxCap,Fleet=true};capacity.Wingmates.Add(ally);capacity.Targets.Add(new(){Id=ally.Id,Kind=TargetKind.Raider,Friendly=true,Profile=profile,Position=capacity.Player.Position+new Vector3(3000+i,0,0),Shield=ally.Shield,Armor=ally.Armor,Hull=ally.Hull,Cap=ally.Cap});}check(capacity.BridgeSpecial(true)&&capacity.LastBridgePassengers==30&&capacity.Wingmates.Count(w=>w.System=="umbra")==30&&capacity.Wingmates.Count(w=>w.System=="rook")==2,"source thirty-passenger limit leaves overflow behind");
  var filters=Fixture();filters.Wingmates.Clear();filters.Targets.Clear();foreach(var source in new[]{"Sin","Helios","Pilgrim","Purifier","Viator","Proteus","Endurance","Dominix"}){var profile=new Ship();profile.ApplyFleetHull(FleetCatalog.Source(source));if(source=="Proteus")profile.StrategicSubsystems["Defensive"]=ShipBatch28.For(profile.CombatHull,"Defensive").Single(x=>x.Name.Contains("Covert")).Id;var ally=new Wingmate{Id=source,HullId=profile.CombatHull,Fleet=true,Hull=profile.MaxHull,Armor=profile.MaxArmor,Shield=profile.MaxShield,Cap=profile.MaxCap};filters.Wingmates.Add(ally);filters.Targets.Add(new(){Id=source,Kind=TargetKind.Raider,Friendly=true,Profile=profile,Position=filters.Player.Position+new Vector3(3000,0,0),Hull=ally.Hull,Shield=ally.Shield,Armor=ally.Armor,Cap=ally.Cap});}check(filters.BridgeSpecial(true)&&filters.LastBridgePassengers==6&&filters.Wingmates.Single(x=>x.Id=="Endurance").System=="rook"&&filters.Wingmates.Single(x=>x.Id=="Dominix").System=="rook","covert-eligible source hulls and strategic subsystem admitted; normal cloak and combat hulls excluded");
  foreach(string invalid in new[]{"outside","cloaked","nonfleet","dead","spooling","disrupted"}){var w=Fixture();var ally=w.Targets.Single();switch(invalid){case "outside":ally.Position=w.Player.Position+new Vector3(10001,0,0);break;case "cloaked":ally.Profile!.Special[0]=new(){ModuleId="sp_ghost",Active=true};break;case "nonfleet":w.Wingmates[0].Fleet=false;break;case "dead":ally.Hull=0;break;case "spooling":ally.Profile!.Mobility[0]=new(){ModuleId=MobilityCatalog.All.First(d=>d.Kind=="MJD").Id,Active=true,CycleLeft=10};break;case "disrupted":w.EwarEffects.Add(new(){SourceId="enemy",TargetId=ally.Id,Kind=EwarKind.Scram,Strength=100,Remaining=60});break;}check(w.BridgeSpecial(true)&&w.LastBridgePassengers==0&&w.Wingmates[0].System=="rook","ineligible passenger left behind / "+invalid);}
  foreach(string why in new[]{"fuel","beacon","range","tackle","capacitor","offline","docked"}){var w=Fixture();switch(why){case "fuel":w.CargoItems["jump_fuel"]=0;break;case "beacon":w.SelectedJumpBeacon()!.Left=0;break;case "range":w.Player.SetStat("jumpDriveRange",.1);break;case "tackle":w.EwarEffects.Add(new(){SourceId="hostile",TargetId="player",Kind=EwarKind.Scram,Key="block",Strength=100,Remaining=60});break;case "capacitor":w.Player.Cap=0;break;case "offline":w.Player.Special.First(x=>x.Definition?.Kind=="CovertPortal").Online=false;break;case "docked":w.Screen=ViewMode.Station;break;}string system=w.SystemId,allies=JsonSerializer.Serialize(w.Wingmates);float stock=w.ItemCount("jump_fuel",false),cap=w.Player.Cap;check(!w.BridgeSpecial(true)&&w.SystemId==system&&near(stock,w.ItemCount("jump_fuel",false))&&near(cap,w.Player.Cap)&&allies==JsonSerializer.Serialize(w.Wingmates),"atomic conduit rejection / "+why);}
 }
